window.fitCard = function(){
  const card = document.getElementById('card');
  const cs = getComputedStyle(card);
  const max = parseFloat(cs.getPropertyValue('--ttlmax')) || 999;
  let ttl = parseFloat(cs.getPropertyValue('--ttl'));
  const set = v => card.style.setProperty('--ttl', v + 'px');
  let guard = 0;
  // shrink until it fits
  while (!fits() && ttl > 18 && guard++ < 200){ ttl -= 1; set(ttl); }
  // then grow while it still fits (bounded by --ttlmax)
  guard = 0;
  while (ttl < max && guard++ < 200){
    ttl += 1; set(ttl);
    if (!fits()){ ttl -= 1; set(ttl); break; }
  }
  return {ttl, ok: fits()};
};

