    if(r.width===0&&r.height===0) continue;
    if(r.left<cb.left-1||r.right>cb.right+1||r.top<cb.top-1||r.bottom>cb.bottom+1)
      issues.push('overflow: '+(el.className||el.tagName));
    if(el.scrollWidth>el.clientWidth+1 && getComputedStyle(el).overflow!=='hidden')
      issues.push('h-clip: '+(el.className||el.tagName));
  }
  const keys=['.brand','.colL','.title','.foot'];
  const bx=keys.map(k=>[k,document.querySelector(k).getBoundingClientRect()]);
  for(let i=0;i<bx.length;i++)for(let j=i+1;j<bx.length;j++){
    const a=bx[i][1],b=bx[j][1];
    if(a.left<b.right-1&&b.left<a.right-1&&a.top<b.bottom-1&&b.top<a.bottom-1)
      issues.push('overlap: '+bx[i][0]+' / '+bx[j][0]);
  }
  const av=document.querySelector('.avatar').getBoundingClientRect();
  if(Math.abs(av.width-av.height)>0.5) issues.push('avatar not square');
